import json,subprocess,pathlib,time,sys
base=pathlib.Path('/tmp/engine-node-types-20261106');root=pathlib.Path('/home/holo/line');runner=base/'runner';ref=pathlib.Path('/tmp/engine-candidate-demand-20261105/reference');wasm='scripts/lib/native_motion/engine.wasm'
common=['taskset','-c','2','node',str(runner/'tools/measure/engine_ab.ts'),'--mode=compile','--reference='+str(ref/wasm),'--candidate='+str(runner/wasm),'--reference-root='+str(ref),'--confidence=.95','--confirm-rounds=24']
def run(name,args,cmd=common,cwd=runner):
 with (base/(name+'.log')).open('w') as f:
  result=subprocess.run(cmd+args+['--out='+str(base/name)],cwd=cwd,stdout=f,stderr=subprocess.STDOUT)
 if result.returncode:raise RuntimeError(name+' exited '+str(result.returncode))
 r=json.loads((base/name/'result.json').read_text());print(name,r['decision'],flush=True);return r
screen=run('screen',['--cells=61','--rounds=12','--warmup=5','--reps=3','--margin-pct=0','--seed=1729'])
if screen['decision']['verdict']!='FASTER':sys.exit('Screen did not qualify; no confirmation')
large=run('larger',['--cells=62','--rounds=12','--warmup=5','--reps=3','--margin-pct=2','--seed=1729'])
cold=run('cold',['--cells=61','--rounds=12','--warmup=0','--reps=1','--margin-pct=5','--seed=1729'])
for label,result,bound in [('larger',large,2),('cold',cold,5)]:
 if result['decision']['intervalPct'][1]>bound:sys.exit(label+' failed regression bound')
for result in [screen,large,cold]:
 for cell in result['resources']:
  a,b=[arm['resources'] for arm in cell['arms']]
  for key,bound in [('wasmLinearMemoryBytes',1.05),('processMaxRssBytes',1.15)]:
   if b[key]/a[key]>bound:sys.exit(f'Resource guard failed: {key}')
confirm=run('confirm',['--cells=61','--stage=confirm','--rounds=24','--warmup=5','--reps=3','--margin-pct=0','--seed=2718','--screen='+str(base/'screen/result.json')])
null=run('native-null',['--cells=61','--rounds=12','--warmup=5','--reps=3','--margin-pct=2','--seed=1729'],cmd=['taskset','-c','2','node',str(root/'tools/measure/engine_ab.ts'),'--mode=compile','--reference='+str(root/wasm),'--candidate='+str(root/wasm),'--confidence=.95','--confirm-rounds=24'],cwd=root)

